const scheduleSection=document.createElement('section');scheduleSection.id='scheduleSection';$('.tasksection').before(scheduleSection);
let projectPanel='tasks';
function getSchedule(){const s=data.projects.find(p=>p.id===selected)?.schedule;return s?normalizeSchedule(s):null}
function commitSchedule(){try{localStorage.setItem(key,JSON.stringify(data));const label=$('#scheduleSaved');if(label)label.textContent='Guardado en este navegador';return true}catch{toast('No se pudo guardar el cronograma. Exporta tus datos para conservarlo.');return false}}
function drawSchedule(){
 const p=data.projects.find(p=>p.id===selected);scheduleSection.hidden=!p;if(!p)return;
 scheduleSection.innerHTML=`<div class="projectPanels"><button data-panel="tasks" class="${projectPanel==='tasks'?'primary':''}">Tareas y evidencias</button><button data-panel="schedule" class="${projectPanel==='schedule'?'primary':''}">▦ Cronograma de obra</button></div><div id="scheduleBody" ${projectPanel==='tasks'?'hidden':''}></div>`;
 $('.tasksection').hidden=projectPanel!=='tasks';if(projectPanel!=='schedule'){$('#scheduleBody').hidden=true;return}
 const el=$('#scheduleBody'),s=getSchedule();
 if(!s){el.innerHTML='<div class="scheduleEmpty"><h2>Planifica tu obra, día a día o semana a semana.</h2><p>Crea una tabla con capítulos, actividades, duración y periodos en cian.</p><label>Escala inicial<select id="newScheduleUnit"><option value="weeks">Semanas</option><option value="days">Días</option></select></label><button class="primary" id="createSchedule">＋ Crear cronograma</button><button id="templateSchedule">Usar plantilla de obra</button></div>';return}
 const daily=s.unit==='days',count=scheduleCount(s),max=daily?728:104,unit=daily?'día':'semana',plural=daily?'días':'semanas';
 el.innerHTML=`<div class="sectionhead"><div><h2>Cronograma de obra</h2><p class="muted" id="scheduleSaved">Guardado en este navegador</p></div><button class="primary" id="schedulePDF">↓ Exportar PDF</button></div><div class="scheduleControls"><label>Inicio de la obra<input id="scheduleStart" type="date" value="${esc(s.start)}"></label><label>Escala del cronograma<select id="scheduleUnit"><option value="weeks" ${daily?'':'selected'}>Semanas</option><option value="days" ${daily?'selected':''}>Días</option></select></label><label>${daily?'Días':'Semanas'} (1–${max})<input id="schedulePeriods" type="number" min="1" max="${max}" value="${count}"></label><button id="addActivity">＋ Actividad</button><button id="addGroup">＋ Capítulo</button></div><p class="muted">Haz clic en cada ${unit} para marcarlo o desmarcarlo. La duración suma los días programados. Usa ↔ para definir un periodo completo.</p><p class="muted">Días calendario, incluidos fines de semana. Cambiar la escala conserva las fechas y marcas. Las semanas se cuentan desde el inicio de la obra; el rayado indica una semana parcialmente programada.</p><div class="scheduleScroll"><table class="scheduleTable"><thead><tr><th>ACTIVIDAD</th><th>DURACIÓN</th>${Array.from({length:count},(_,i)=>`<th>${daily?'D':'S'}${i+1}<small>${schedulePeriodDate(s,i+1)}</small></th>`).join('')}<th>GESTIONAR</th></tr></thead><tbody>${s.rows.map((r,i)=>`<tr class="${r.group?'scheduleGroup':''}" data-row="${r.id}"><th><input aria-label="Nombre de ${r.group?'capítulo':'actividad'} ${i+1}" maxlength="160" data-row-name="${r.id}" value="${esc(r.name)}"></th><td class="duration">${r.group?'—':scheduleDuration(s,r)}</td>${Array.from({length:count},(_,j)=>{if(r.group)return '<td></td>';const state=schedulePeriodState(s,r,j+1);return `<td><button class="weekCell ${state.marked?'marked':''} ${state.partial?'partial':''}" data-period="${j+1}" data-row-id="${r.id}" aria-label="${esc(r.name)}, ${unit} ${j+1}" title="${state.count} de ${state.total} días programados; clic para ${state.marked?'desmarcar':'marcar'}" aria-pressed="${state.marked}"></button></td>`}).join('')}<td class="rowActions"><button data-up="${r.id}" aria-label="Subir fila" ${i===0?'disabled':''}>↑</button><button data-down="${r.id}" aria-label="Bajar fila" ${i===s.rows.length-1?'disabled':''}>↓</button><button data-range="${r.id}" ${r.group?'hidden':''} aria-label="Definir periodo">↔</button><button data-remove-row="${r.id}" aria-label="Eliminar fila">✕</button></td></tr>`).join('')}</tbody></table></div>${s.rows.length?'':'<p class="empty">Agrega una actividad o un capítulo para comenzar.</p>'}<p class="muted">Cian = periodo programado · Cada proyecto tiene su propia escala. El PDF se divide en páginas si supera 20 ${plural} o 22 filas.</p>`;
}
function createSchedule(template){const p=data.projects.find(p=>p.id===selected);if(!p)return;const unit=$('#newScheduleUnit').value,rows=template?[['OBRAS PROVISIONALES',true],['Obras provisionales',false,1,4],['TRABAJOS PRELIMINARES',true],['Limpieza y replanteo',false,1,4],['Movimiento de tierras',false,3,6],['ESTRUCTURA',true],['Obras de concreto simple',false,5,8],['Obras de concreto armado',false,8,12],['Acero de refuerzo',false,8,12],['ACABADOS Y ENTREGA',true],['Acabados',false,13,18],['Inspección y entrega',false,19,20]]:[];p.schedule={start:new Date().toLocaleDateString('en-CA'),unit,calendarDays:unit==='days'?20:140,weeks:unit==='days'?3:20,rows:rows.map(([name,group,a,b])=>({id:crypto.randomUUID(),name,group,activeDays:group?[]:Array.from({length:(b-a+1)*(unit==='days'?1:7)},(_,i)=>(a-1)*(unit==='days'?1:7)+i+1)}))};syncLegacySchedule(p.schedule);drawSchedule();commitSchedule()}
scheduleSection.addEventListener('change',e=>{const s=getSchedule();if(!s)return;if(e.target.id==='scheduleUnit'){s.unit=e.target.value;commitSchedule();drawSchedule();toast('Escala cambiada; fechas y marcas conservadas')}if(e.target.id==='scheduleStart'){s.start=e.target.value;commitSchedule();drawSchedule()}if(e.target.id==='schedulePeriods'){const n=Number(e.target.value),max=s.unit==='days'?728:104,newDays=n*scheduleStep(s);if(!Number.isInteger(n)||n<1||n>max){toast('Elige entre 1 y '+max+' periodos');e.target.value=scheduleCount(s);return}if(newDays<s.calendarDays&&s.rows.some(r=>r.activeDays.some(d=>d>newDays))&&!confirm('Se eliminarán las marcas fuera de la nueva duración del cronograma. ¿Continuar?')){e.target.value=scheduleCount(s);return}resizeSchedule(s,n);commitSchedule();drawSchedule()}if(e.target.dataset.rowName){const row=s.rows.find(r=>r.id===e.target.dataset.rowName);row.name=e.target.value.trim()||'Sin nombre';e.target.value=row.name;commitSchedule()}});
scheduleSection.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.panel){projectPanel=b.dataset.panel;drawSchedule();return}if(b.id==='createSchedule'||b.id==='templateSchedule'){createSchedule(b.id==='templateSchedule');return}const s=getSchedule();if(!s)return;let changed=false;
 if(b.id==='addActivity'||b.id==='addGroup'){s.rows.push({id:crypto.randomUUID(),name:b.id==='addGroup'?'Nuevo capítulo':'Nueva actividad',group:b.id==='addGroup',active:[],activeDays:[]});changed=true}
 if(b.dataset.period){const row=s.rows.find(r=>r.id===b.dataset.rowId);setSchedulePeriod(s,row,Number(b.dataset.period));changed=true}
 if(b.dataset.up||b.dataset.down){const id=b.dataset.up||b.dataset.down,i=s.rows.findIndex(r=>r.id===id),j=i+(b.dataset.up?-1:1);if(j>=0&&j<s.rows.length){[s.rows[i],s.rows[j]]=[s.rows[j],s.rows[i]];changed=true}}
 if(b.dataset.removeRow&&confirm('¿Eliminar esta fila del cronograma?')){s.rows=s.rows.filter(r=>r.id!==b.dataset.removeRow);changed=true}
 if(b.dataset.range){const r=s.rows.find(r=>r.id===b.dataset.range),count=scheduleCount(s),label=s.unit==='days'?'Día':'Semana',a=prompt(label+' de inicio (1 a '+count+')',r.activeDays.length?Math.ceil(Math.min(...r.activeDays)/scheduleStep(s)):1);if(a===null)return;const z=prompt(label+' final (incluido)',r.activeDays.length?Math.ceil(Math.max(...r.activeDays)/scheduleStep(s)):a);if(z===null)return;const start=Number(a),end=Number(z);if(!Number.isInteger(start)||!Number.isInteger(end)||start<1||end<start||end>count){toast('Periodo inválido');return}rangeSchedule(s,r,start,end);changed=true}
 if(b.id==='schedulePDF'){const p=data.projects.find(p=>p.id===selected),bytes=schedulePDF(p,s),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download='cronograma-'+p.name.replace(/[^\p{L}\p{N}-]/gu,'-')+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('PDF exportado');return}
 if(changed){drawSchedule();commitSchedule();if(b.id==='addActivity'||b.id==='addGroup')$('#scheduleBody tbody tr:last-child input')?.focus()}
});
const renderBeforeSchedule=render;render=function(){renderBeforeSchedule();drawSchedule()};drawSchedule();

